  "editions": [
    {
      "edition": "standard",
      "verdict": "revise",
      "checks": {
        "complete_coverage": true,
        "no_added_claims": false,
        "names_and_negations": true,
        "speaker_attribution": true,
        "source_choices_and_notes": true,
        "terminology_policy": true
      },
      "findings": [
        {
          "source_quote": "οὐκ ἀπεβλήθησαν δέ",
          "english_quote": "Preserve the narrated opportunity for fitting rejected stones without adding later procedures; expose editorial supplements and unresolved wording.",
          "issue": "The theological rationale misidentifies the stones awaiting fitting as rejected stones. Paragraph 4 explicitly says these remaining stones were not rejected. The rejected stones in paragraphs 5–6 are a distinct group carried back to the mountains; this section does not narrate an opportunity to fit that group into the building.",
          "suggested_revision": "Revise the rationale to distinguish the non-rejected stones set aside for fitting from the rejected stones returned to the mountains. Proposed wording for fresh review: “Preserve the distinction between the non-rejected stones set aside for fitting and the rejected stones returned to the mountains; expose editorial supplements and unresolved wording.”",
          "severity": "major"
        }
      ]
    },
    {
      "edition": "simplified",
      "verdict": "revise",
      "checks": {
        "complete_coverage": false,
        "no_added_claims": false,
        "names_and_negations": true,
        "speaker_attribution": true,
        "source_choices_and_notes": true,
        "terminology_policy": true
      },
      "findings": [
        {
          "source_quote": "Εἶτα ἦλθε κατανοῆσαι τοὺς λευκοὺς καὶ στρογγύλους λίθους",
          "english_quote": "Next he examined the white, round stones.",
          "issue": "The simplified wording omits his coming to examine the stones, replacing the narrated movement and purpose with examination alone.",
          "suggested_revision": "Restore the movement and purpose. Proposed wording for fresh review: “Next he came to examine the white, round stones.”",
          "severity": "minor"
        },
        {
          "source_quote": "ἐκέλευσε δὲ αὐτὰς ὁ ποιμὴν ἆραι τοὺς λίθους τοὺς ἀποβεβλημένους ἐκ τῆς οἰκοδομῆς, καὶ ἀπενεγκεῖν αὐτοὺς εἰς τὰ ὄρη ὅθεν καὶ ἠνέχθησαν.",
          "english_quote": "The shepherd told them to carry the rejected stones back to the mountains they came from.",
          "issue": "The command loses both the explicit lifting action and the identification of the stones as rejected from the building. The latter distinction is important because the preceding stones were expressly not rejected.",
          "suggested_revision": "Restore both details. Proposed wording for fresh review: “The shepherd told them to lift the stones rejected from the building and carry them back to the mountains they came from.”",
          "severity": "major"
        },
        {
          "source_quote": "οὐκ ἀπεβλήθησαν δέ",
          "english_quote": "Preserve the narrated opportunity for fitting rejected stones without adding later procedures; expose editorial supplements and unresolved wording.",
          "issue": "Independently of the simplified reader text, its theological rationale contradicts the source's distinction between non-rejected stones awaiting fitting and rejected stones returned to the mountains. No opportunity for fitting the rejected group is narrated here.",
          "suggested_revision": "Revise the rationale to identify the stones set aside for fitting as non-rejected, and keep them distinct from the stones returned to the mountains. Any replacement metadata requires fresh review.",
          "severity": "major"
        },
        {
          "source_quote": "αἱ δὲ παρθένοι ἄρασαι ἥρμοσαν εἰς τὰ ἐξώτερα μέρη τῆς οἰκοδομῆς.",
          "english_quote": "Retain all seven stone conditions, the three strikes, the two-day interval, inside/outside placement, setting aside versus rejection and no-joint selection; preserve all substantive alternative notes.",
          "issue": "The simplification metadata incorrectly claims retention of details absent from this selected section and its supplied English: seven stone conditions, three strikes, a two-day interval, and inside placement. This section specifies outside placement, setting aside versus rejection, and the selected no-joint reading.",
          "suggested_revision": "Replace the cross-section checklist with an accurate account of this section's simplification choices, retaining only details actually present. Do not claim coverage of material from other sections.",
          "severity": "minor"
        }
      ]
    }
  ],
  "summary": "Both editions require revision. The standard reader text covers the selected source, but its theological metadata confuses non-rejected and rejected stones. The simplified edition independently has omissions and inaccurate metadata. Both appropriately retain the disclosed working readings, including certainty and the no-joint selection, while exposing alternatives and bracketed material. This assessment concerns the supplied Greek and attributed project reports; it does not authenticate unseen manuscripts or certify exhaustive collation. Proposed corrections remain subject to fresh review."
}
